import os,glob,re,json
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))
def f(g):
    g=[r[:] for r in g]; H,W=len(g),len(g[0])
    # find connected components of non-background colors
    seen=[[False]*W for _ in range(H)]; bg=max(set(v for r in g for v in r), key=lambda c: sum(r.count(c) for r in g))
    import sys; sys.setrecursionlimit(10000)
    comps=[]
    for i in range(H):
        for j in range(W):
            if not seen[i][j] and g[i][j]!=bg:
                c=g[i][j]; stack=[(i,j)]; cells=[]
                while stack:
                    y,x=stack.pop()
                    if 0<=y<H and 0<=x<W and not seen[y][x] and g[y][x]==c:
                        seen[y][x]=True; cells.append((y,x))
                        stack.extend([(y+1,x),(y-1,x),(y,x+1),(y,x-1)])
                comps.append((c,cells))
    for c,cells in comps:
        ys=[p[0] for p in cells]; xs=[p[1] for p in cells]
        r0,r1,c0,c1=min(ys),max(ys),min(xs),max(xs)
        for y in range(r0+1,r1):
            for x in range(c0+1,c1):
                if g[y][x]==c: g[y][x]=8
    return g
print(json.dumps(f(G['Demo pair 1 input']))==json.dumps(G['Demo pair 1 output']))
out=f(G['Test input']); print(json.dumps(out))
